import{_ as n,a0 as d,w as p,s as g,I as t,x as s,a1 as a,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何使用 Tig 瀏覽 Git 日誌 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Tig 瀏覽 Git 日誌 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Tig 瀏覽 Git 日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Tig 瀏覽 Git 日誌 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190627 How to use Tig to browse Git logs","title":"如何使用 Tig 瀏覽 Git 日誌","tag":"201907","desc":""},"relativePath":"201907/20190627 How to use Tig to browse Git logs.md","filePath":"[post].md"}'),r={name:"201907/20190627 How to use Tig to browse Git logs.md"};function h(u,i,b,k,c,f){const e=d("Link");return p(),g("div",null,[i[30]||(i[30]=t("h1",{id:"如何使用-tig-瀏覽-git-日誌",tabindex:"-1"},[s("如何使用 Tig 瀏覽 Git 日誌 "),t("a",{class:"header-anchor",href:"#如何使用-tig-瀏覽-git-日誌","aria-label":"Permalink to “如何使用 Tig 瀏覽 Git 日誌”"},"​")],-1)),i[31]||(i[31]=t("blockquote",null,[t("p",null,"Tig 可不僅僅是 Git 的文本界面。以下是它如何增強你的日常工作流程。")],-1)),i[32]||(i[32]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/07/111847v1zx3qk5qqhklyjp.png",alt:""})],-1)),t("p",null,[i[1]||(i[1]=s("如果你使用 Git 作為你的版本控制系統，你可能已經讓自己接受了 Git 是一個複雜的野獸的事實。它是一個很棒的工具，但瀏覽 Git 倉庫可能很麻煩。因此像 ",-1)),a(e,{href:"https://jonas.github.io/tig/"},{default:l(()=>[...i[0]||(i[0]=[s("Tig",-1)])]),_:1}),i[2]||(i[2]=s(" 這樣的工具出現了。",-1))]),t("p",null,[i[4]||(i[4]=s("來自 ",-1)),a(e,{href:"http://manpages.ubuntu.com/manpages/bionic/man1/tig.1.html"},{default:l(()=>[...i[3]||(i[3]=[s("Tig 手冊頁",-1)])]),_:1}),i[5]||(i[5]=s("：",-1))]),i[33]||(i[33]=o('<blockquote><p>Tig 是 <code>git</code>(1) 的基於 ncurses 的文本界面。它主要用作 Git 倉庫瀏覽器，但也有助於在塊級別暫存提交更改，並作為各種 Git 命令的輸出分頁器。</p></blockquote><p>這基本上意味着 Tig 提供了一個可以在終端中運行的基於文本的用户界面。Tig 可以讓你輕鬆瀏覽你的 Git 日誌，但它可以做的遠不止讓你從最後的提交跳到前一個提交。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig.jpg" alt="Tig screenshot" title="Tig screenshot"></p><p>這篇快速入門的 Tig 中的許多例子都是直接從其出色的手冊頁中拿出來的。我強烈建議你閲讀它以瞭解更多信息。</p><h3 id="安裝-tig" tabindex="-1">安裝 Tig <a class="header-anchor" href="#安裝-tig" aria-label="Permalink to “安裝 Tig”">​</a></h3><ul><li>Fedora 和 RHEL： <code>sudo dnf install tig</code></li><li>Ubuntu 和 Debian： <code>sudo apt install tig</code></li><li>MacOS： <code>：brew install tig</code></li></ul>',6)),t("p",null,[i[7]||(i[7]=s("有關更多方式，請參閲官方",-1)),a(e,{href:"https://jonas.github.io/tig/INSTALL.html"},{default:l(()=>[...i[6]||(i[6]=[s("安裝説明",-1)])]),_:1}),i[8]||(i[8]=s("。",-1))]),i[34]||(i[34]=o('<h3 id="瀏覽當前分支中的提交" tabindex="-1">瀏覽當前分支中的提交 <a class="header-anchor" href="#瀏覽當前分支中的提交" aria-label="Permalink to “瀏覽當前分支中的提交”">​</a></h3><p>如果要瀏覽分支中的最新提交，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig</span></span></code></pre></div><p>就是這樣。這個三字符命令將啓動一個瀏覽器，你可以在其中瀏覽當前分支中的提交。你可以將其視為 <code>git log</code> 的封裝器。</p><p>要瀏覽這些輸出，可以使用向上和向下箭頭鍵從一個提交移動到另一個提交。按回車鍵將會垂直分割窗口，右側包含所選提交的內容。你可以繼續在左側的提交歷史記錄中上下瀏覽，你的更改將顯示在右側。使用 <code>k</code> 和 <code>j</code> 可以逐行上下瀏覽，<code>-</code> 和空格鍵可以在右側上下翻頁。使用 <code>q</code> 退出右側窗格。</p><p>搜索 <code>tig</code> 輸出也很簡單。使用 <code>/</code> （向前）或 <code>?</code> （向後）在左右窗格中搜索。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-search.png" alt="Searching Tig" title="Searching Tig"></p><p>這些就足以讓你瀏覽你的提交信息了。這裏有很多的鍵綁定，但單擊 <code>h</code> 將顯示“幫助”菜單，你可以在其中發現其導航和命令選項。你還可以使用 <code>/</code> 和 <code>?</code> 來搜索“幫助”菜單。使用 <code>q</code> 退出幫助。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-help.png" alt="Tig Help" title="Tig Help"></p><h3 id="瀏覽單個文件的修改" tabindex="-1">瀏覽單個文件的修改 <a class="header-anchor" href="#瀏覽單個文件的修改" aria-label="Permalink to “瀏覽單個文件的修改”">​</a></h3><p>由於 Tig 是 <code>git log</code> 的封裝器，它可以方便地接受可以傳遞給 <code>git log</code> 的相同參數。例如，要瀏覽單個文件的提交歷史記錄，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig README.md</span></span></code></pre></div><p>將其與被封裝的 Git 命令的輸出進行比較，以便更清楚地瞭解 Tig 如何增強輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log README.md</span></span></code></pre></div><p>要在原始 Git 輸出中包含補丁，你可以添加 <code>-p</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log -p README.md</span></span></code></pre></div><p>如果要將提交範圍縮小到特定日期範圍，請嘗試以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><p>再一次，你可以將其與原始的 Git 版本進行比較：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><h3 id="瀏覽誰更改了文件" tabindex="-1">瀏覽誰更改了文件 <a class="header-anchor" href="#瀏覽誰更改了文件" aria-label="Permalink to “瀏覽誰更改了文件”">​</a></h3><p>有時你想知道誰對文件進行了更改以及原因。命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig blame README.md</span></span></code></pre></div><p>器本質上是 <code>git blame</code> 的封裝。正如你所期望的那樣，它允許你查看誰是編輯指定行的最後一人，它還允許你查看到引入該行的提交。這有點像 vim 的 <code>vim-fugitive</code> 插件提供的 <code>:Gblame</code> 命令。</p><h3 id="瀏覽你的暫存區" tabindex="-1">瀏覽你的暫存區 <a class="header-anchor" href="#瀏覽你的暫存區" aria-label="Permalink to “瀏覽你的暫存區”">​</a></h3><p>如果你像我一樣，你可能會在你的暫存區做了許多修改。你很容易忘記它們。你可以通過以下方式查看暫存處中的最新項目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash show -p stash@{0}</span></span></code></pre></div><p>你可以通過以下方式找到第二個最新項目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash show -p stash@{1}</span></span></code></pre></div><p>以此類推。如果你在需要它們時調用這些命令，那麼你會有比我更清晰的記憶。</p><p>與上面的 Git 命令一樣，Tig 可以通過簡單的調用輕鬆增強你的 Git 輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig stash</span></span></code></pre></div><p>嘗試在有暫存的倉庫中執行此命令。你將能夠瀏覽<em>並搜索</em>你的暫存項，快速瀏覽你的那些修改。</p><h3 id="瀏覽你的引用" tabindex="-1">瀏覽你的引用 <a class="header-anchor" href="#瀏覽你的引用" aria-label="Permalink to “瀏覽你的引用”">​</a></h3><p>Git ref 是指你提交的東西的哈希值。這包括文件和分支。使用 <code>tig refs</code> 命令可以瀏覽所有的 ref 並深入查看特定提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig refs</span></span></code></pre></div><p>完成後，使用 <code>q</code> 回到前面的菜單。</p><h3 id="瀏覽-git-狀態" tabindex="-1">瀏覽 git 狀態 <a class="header-anchor" href="#瀏覽-git-狀態" aria-label="Permalink to “瀏覽 git 狀態”">​</a></h3><p>如果要查看哪些文件已被暫存，哪些文件未被跟蹤，請使用 <code>tig status</code>，它是 <code>git status</code> 的封裝。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-status.png" alt="Tig status" title="Tig status"></p><h3 id="瀏覽-git-grep" tabindex="-1">瀏覽 git grep <a class="header-anchor" href="#瀏覽-git-grep" aria-label="Permalink to “瀏覽 git grep”">​</a></h3><p>你可以使用 <code>grep</code> 命令在文本文件中搜索表達式。命令 <code>tig grep</code> 允許你瀏覽 <code>git grep</code> 的輸出。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig grep -i foo lib/Bar</span></span></code></pre></div><p>它會讓你瀏覽 <code>lib/Bar</code> 目錄中以大小寫敏感的方式搜索 <code>foo</code> 的輸出。</p><h3 id="通過標準輸入管道輸出給-tig" tabindex="-1">通過標準輸入管道輸出給 Tig <a class="header-anchor" href="#通過標準輸入管道輸出給-tig" aria-label="Permalink to “通過標準輸入管道輸出給 Tig”">​</a></h3><p>如果要將提交 ID 列表傳遞給 Tig，那麼必須使用 <code>--stdin</code> 標誌，以便 <code>tig show</code> 從標準輸入讀取。否則，<code>tig show</code> 會在沒有輸入的情況下啓動（出現空白屏幕）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git rev-list --author=olaf HEAD | tig show --stdin</span></span></code></pre></div><h3 id="添加自定義綁定" tabindex="-1">添加自定義綁定 <a class="header-anchor" href="#添加自定義綁定" aria-label="Permalink to “添加自定義綁定”">​</a></h3>',48)),t("p",null,[i[10]||(i[10]=s("你可以使用 ",-1)),a(e,{href:"https://en.wikipedia.org/wiki/Run_commands"},{default:l(()=>[...i[9]||(i[9]=[s("rc",-1)])]),_:1}),i[11]||(i[11]=s(" 文件自定義 Tig。以下是如何根據自己的喜好添加一些有用的自定義鍵綁定的示例。",-1))]),i[35]||(i[35]=o(`<p>在主目錄中創建一個名為 <code>.tigrc</code> 的文件。在你喜歡的編輯器中打開 <code>~/.tigrc</code> 並添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 應用選定的暫存內容</span></span>
<span class="line"><span>bind stash a !?git stash apply %(stash)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 丟棄選定的暫存內容</span></span>
<span class="line"><span>bind stash x !?git stash drop %(stash)</span></span></code></pre></div><p>如上所述，運行 <code>tig stash</code> 以瀏覽你的暫存。但是，通過這些綁定，你可以按 <code>a</code> 將暫存中的項目應用到倉庫，並按 <code>x</code> 從暫存中刪除項目。請記住，你要在瀏覽暫存<em>列表</em>時，才能執行這些命令。如果你正在瀏覽暫存<em>項</em>，請輸入 <code>q</code> 退出該視圖，然後按 <code>a</code> 或 <code>x</code> 以獲得所需效果。</p>`,3)),t("p",null,[i[13]||(i[13]=s("有關更多信息，你可以閲讀有關 ",-1)),a(e,{href:"https://github.com/jonas/tig/wiki/Bindings"},{default:l(()=>[...i[12]||(i[12]=[s("Tig 鍵綁定",-1)])]),_:1}),i[14]||(i[14]=s("。",-1))]),i[36]||(i[36]=t("h3",{id:"總結",tabindex:"-1"},[s("總結 "),t("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),i[37]||(i[37]=t("p",null,"我希望這有助於演示 Tig 如何增強你的日常工作流程。Tig 可以做更強大的事情（比如暫存代碼行），但這超出了這篇介紹性文章的範圍。這裏有足夠的讓你置身於危險的信息，但還有更多值得探索的地方。",-1)),i[38]||(i[38]=t("hr",null,null,-1)),t("p",null,[i[16]||(i[16]=s("via: ",-1)),a(e,{href:"https://opensource.com/article/19/6/what-tig"},{default:l(()=>[...i[15]||(i[15]=[s("https://opensource.com/article/19/6/what-tig",-1)])]),_:1})]),t("p",null,[i[21]||(i[21]=s("作者：",-1)),a(e,{href:"https://opensource.com/users/oalders/users/mbbroberg/users/marcobravo"},{default:l(()=>[...i[17]||(i[17]=[s("Olaf Alders",-1)])]),_:1}),i[22]||(i[22]=s(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[18]||(i[18]=[s("lujun9972",-1)])]),_:1}),i[23]||(i[23]=s(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:l(()=>[...i[19]||(i[19]=[s("geekpi",-1)])]),_:1}),i[24]||(i[24]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:l(()=>[...i[20]||(i[20]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[27]||(i[27]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[25]||(i[25]=[s("LCTT",-1)])]),_:1}),i[28]||(i[28]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:l(()=>[...i[26]||(i[26]=[s("Linux中國",-1)])]),_:1}),i[29]||(i[29]=s(" 榮譽推出",-1))])])}const y=n(r,[["render",h]]);export{C as __pageData,y as default};
